import type { BrandAvatarItemProps } from 'components/BrandAvatar/Components/BrandAvatarItem/interface';

/** Shared BFF prefix block for drilled Deep Dive waterfall views. */
export const PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX = {
  labels: ["'25 FY", 'Expiration', 'Baseline'] as const,
  values: [92.4, -2.8, 89.6] as const,
  formatted: ['92.4', '-2.8', '89.6'] as const,
  disabledIndexes: [0, 1, 2] as const,
  filterValues: [null, null, null] as const,
  images: [
    { title: "'25 FY" },
    { title: 'Expiration' },
    { title: 'Baseline' },
  ] as BrandAvatarItemProps[],
};

export const PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_LE_VALUE = 101.8;

const BASELINE_IMAGE_INDEX = 2;

export function buildPerformanceAndBreakdownDeepDiveImagesData(
  anchor: { src: string; alt: string },
  entityTitles: readonly string[],
): BrandAvatarItemProps[] {
  const prefixImages =
    PERFORMANCE_AND_BREAKDOWN_DEEP_DIVE_WATERFALL_PREFIX.images.map(
      (item, index) =>
        index === BASELINE_IMAGE_INDEX
          ? { ...item, mainBrand: anchor }
          : { ...item },
    );

  return [
    ...prefixImages,
    ...entityTitles.map((title) => ({ title })),
    {
      title: "'26 LE",
      mainBrand: anchor,
    },
  ];
}
